def run():
    evidence=OUT/"scientific_evidence"; summaries={r["unit"]:r for r in read_table(evidence/"priority_nine_summary.tsv")}
    source_dir=OUT/"primary_sources"; sources={}
    for key in {o["key"] for o in OBJECTS}:
        path=source_dir/(key+"_primary_fulltext.xml")
        info=dict(primary_fulltext_available=path.exists(),primary_fulltext_file=str(path.relative_to(ROOT)) if path.exists() else None,supplement_content_reviewed=False)
        if path.exists():
            tree=ET.parse(path).getroot(); text=" ".join(tree.itertext())
            info.update(sha256=hashlib.sha256(path.read_bytes()).hexdigest(),accessions=sorted(set(re.findall(r"(?:GSE|PRJNA|E-MTAB-|SRP)[0-9]+",text))),license_declarations=[" ".join("".join(x.itertext()).split())[:1200] for x in tree.findall(".//license")],supplements=[dict(id=x.attrib.get("id"),links=[z.attrib.get("{http://www.w3.org/1999/xlink}href") for z in x.iter() if z.attrib.get("{http://www.w3.org/1999/xlink}href")]) for x in tree.findall(".//supplementary-material")])
        sources[key]=info
    write_json(evidence/"primary_methods_supplement_index.json",sources)
    checklist=[]; panel=[]
    for obj in OBJECTS:
        summary=summaries[obj["unit"]]; d=ROOT/summary["evidence_directory"]; technical=json.loads((d/"technical_audit.json").read_text()) if (d/"technical_audit.json").exists() else json.loads((d/"prior_audit_revalidated.json").read_text())
