        (d/"README.md").write_text("\n".join(lines))
        checklist.append(dict(unit=obj["unit"],canonical_task=obj["task"],source_doi=obj["doi"],input_and_label_review="PENDING",original_row_mapping="PENDING",methods_supplement_review="PARTIAL_PENDING",gene_wt_homology_review="PENDING",data_use_permission="NOT_APPROVED",redistribution_permission="NOT_APPROVED",candidate_disposition="HOLD",hold_reason=obj["hold"],authorized_reviewer_id="",review_signed_at="",approval_evidence_path="",formal_admitted=False))
        panel.append(dict(dataset=obj["unit"],canonical_tasks=[obj["task"]],domain=obj["domain"],candidate_tier=obj["tier"],source_family=obj["source_family"],selection_reason="Biological readout/source coverage; "+obj["definition"],rights="HOLD",scientific_admission="HOLD",formal_score_eligible=False,evidence=summary["evidence_directory"]))
